import z3
weeks = 5
groups = 10
golfers = 40
X = [[z3.Int(f'g{w}_{g}') for g in range(golfers)] for w in range(weeks)]
s = z3.Solver()
for w in range(weeks):
    for g in range(golfers):
        s.add(X[w][g] >= 0, X[w][g] < groups)
for w in range(weeks):
    for grp in range(groups):
        s.add(z3.Sum([z3.If(X[w][g] == grp, 1, 0) for g in range(golfers)]) == 4)
for g1 in range(golfers):
    for g2 in range(g1+1, golfers):
        together = [z3.If(X[w][g1] == X[w][g2], 1, 0) for w in range(weeks)]
        s.add(z3.Sum(together) <= 1)
if s.check() == z3.sat:
    m = s.model()
    solution = []
    for w in range(weeks):
        for p in range(golfers):
            solution.append(m[X[w][p]].as_long())
    print(solution)
